import test from 'node:test';
import assert from 'node:assert/strict';
import { encodeCallerInit, decodeCallerInitResponse } from './zrtc-init.mjs';

// Expected bytes captured from the vendor executable, not generated by this
// encoder. The fixture uses dummy identities/session and contains no secrets.
test('caller init matches the first 183-byte datagram emitted by PC 26.9.10', () => {
  const nativePrefix = '017e0000000000000000a1860100000000000b00028f6fd47ba28601009800';
  const actual = encodeCallerInit({ callerId:100001, calleeId:100002, callId:2077519759, session:'A'.repeat(152) });
  assert.deepEqual(actual, Buffer.concat([Buffer.from(nativePrefix, 'hex'), Buffer.alloc(152, 65)]));
});
test('init encoder rejects truncated identifiers and oversized sessions', () => {
  const valid = {callerId:100001,calleeId:100002,callId:2077519759,session:'A'.repeat(152)};
  for (const id of [0,-1,0x100000000,1.5,'100001']) assert.throws(()=>encodeCallerInit({...valid,callerId:id}),/INVALID_ZRTC_ID/);
  assert.throws(()=>encodeCallerInit({...valid,session:'A'.repeat(1270)}),/ZRTC_SESSION_TOO_LARGE/);
});

test('response parser validates the call binding and rejects all truncations of a success packet', () => {
  // Synthetic response accepted by the offline vendor core, driving it to 416.
  const ack = Buffer.from('027e0000000000000000a1860100000000000b0002000000008f6fd47b4433221109006c6f63616c74657374','hex');
  assert.deepEqual(decodeCallerInitResponse(ack,2077519759),{status:0,callId:2077519759,token:0x11223344,extra:'localtest'});
  assert.throws(()=>decodeCallerInitResponse(ack,123),/ZRTC_CALL_ID_MISMATCH/);
  for(let n=0;n<ack.length;n++) assert.throws(()=>decodeCallerInitResponse(ack.subarray(0,n),2077519759));
  const rejected = Buffer.from(ack.subarray(0,25)); rejected.writeInt32LE(-1,21);
  assert.deepEqual(decodeCallerInitResponse(rejected,2077519759),{status:-1});
});
